mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;log=[]
def get_tok():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b""));tok=json.load(r)["token"];return
        except urllib.error.HTTPError as e:
            w=e.headers.get("Retry-After");time.sleep(float(w) if w else 1)
def get(p):
    global tok
    if not tok:get_tok()
    while True:
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30))
        except urllib.error.HTTPError as e:
            log.append((p,e.code))
            if e.code==401:get_tok()
            elif e.code==404:return None
            elif e.code==429:time.sleep(float(e.headers.get("Retry-After") or 1))
            else:time.sleep(0.5)
        except Exception as e:
            log.append((p,str(e)));time.sleep(0.5)
orders={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in orders:dups+=1
        else:orders[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};tot={"north":0,"south":0,"east":0,"west":0};n=0;odd=[];stat=set()
for o in orders.values():
    stat.add(o["status"])
    if o["status"]!="shipped":continue
    ts=o["placed_at"].replace("Z","+00:00");t=datetime.fromisoformat(ts)
    if t.tzinfo is None:odd.append(("naive",o["id"]));t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust:cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None:odd.append(("nocust",o["id"],c));continue
    a=o["amount_cents"]*(100-cu["discount_pct"]);v=(a+50)//100
    tot[cu["region"]]+=v;n+=1
json.dump({"total_cents":sum(tot.values()),"order_count":n,"duplicates_skipped":dups,"by_region":tot},open("/workspace/result.json","w"),indent=2)
from collections import Counter
print(pages,len(orders),stat,odd[:20],len(odd),Counter(x[1] for x in log),Counter(type(x["amount_cents"]).__name__ for x in orders.values()))
print(set(c["discount_pct"] for c in cust.values() if c))
EOF
